        { sku: 'DEV-HOUR', qty: 3, discountPercent: 5 },
      ],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const subtotal = 5 * 8500 + 3 * 9500;
    const discount = (5 * 8500) * 0.1 + (3 * 9500) * 0.05;
    const vat1 = roundCents((5 * 8500 - (5 * 8500) * 0.1) * 0.21);
    const vat2 = roundCents((3 * 9500 - (3 * 9500) * 0.05) * 0.21);
    const vat = vat1 + vat2;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, discount);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal - discount + vat);
  });

  it('calculates totals with tier discounts applied', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const subtotal = 5 * 8500 + 3 * 9500;
    const discount = (5 * 8500) * 0.05 + (3 * 9500) * 0.05;
    const afterDiscount1 = 5 * 8500 - (5 * 8500) * 0.05;
    const afterDiscount2 = 3 * 9500 - (3 * 9500) * 0.05;
    const vat = roundCents(afterDiscount1 * 0.21) + roundCents(afterDiscount2 * 0.21);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, discount);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal - discount + vat);
  });

  it('applies correct discount when mixing tier and explicit discounts', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-003',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 10 },
        { sku: 'DEV-HOUR', qty: 5, discountPercent: 0 },
      ],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const subtotal = 10 * 8500 + 5 * 9500;
    const tierDiscount = (10 * 8500) * 0.025;
    const explicitDiscount = 0;
    const discount = tierDiscount + explicitDiscount;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, discount);
  });

  it('calculates VAT on line after discount', () => {
    const invoice = {
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 100000;
    const discount = 10000;
    const afterDiscount = 90000;
    const vat = roundCents(90000 * 0.21);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, discount);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal - discount + vat);
  });

  it('calculates VAT with 21% rate', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 10000;
    const vat = roundCents(10000 * 0.21);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal + vat);
  });

  it('calculates VAT with 9% rate', () => {
    const invoice = {
      lines: [{ qty: 100, unitPrice: 1000, discountPercent: 0, vatRate: 9 }],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 100000;
    const vat = roundCents(100000 * 0.09);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, vat);
    assert.equal(totals.total, subtotal + vat);
  });

  it('calculates VAT with 0% rate', () => {
    const invoice = {
      lines: [{ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }],
    };
    const totals = invoiceTotals(invoice);
    assert.equal(totals.subtotal, 10000);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, 0);
    assert.equal(totals.total, 10000);
  });

  it('sums VAT across multiple lines', () => {
    const invoice = {
      lines: [
        { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
        { qty: 5, unitPrice: 2000, discountPercent: 0, vatRate: 9 },
      ],
    };
    const totals = invoiceTotals(invoice);
    const subtotal = 10000 + 10000;
    const vat1 = roundCents(10000 * 0.21);
    const vat2 = roundCents(10000 * 0.09);
    const totalVat = vat1 + vat2;
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, 0);
    assert.equal(totals.vat, totalVat);
    assert.equal(totals.total, subtotal + totalVat);
  });

  it('rounds VAT per line before summing', () => {
    const invoice = {
      lines: [
        { qty: 3, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
        { qty: 3, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      ],
    };
    const totals = invoiceTotals(invoice);
    const vat1 = roundCents(3000 * 0.21);
    const vat2 = roundCents(3000 * 0.21);
    const expectedVat = vat1 + vat2;
    assert.equal(totals.vat, expectedVat);
  });

  it('calculates VAT on amount after discount and tier discount', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 100 }],
    });

    assert(invoiceResult.ok);
    const totals = invoiceTotals(invoiceResult.value);
    const subtotal = 100 * 8500;
    const tierDiscount = subtotal * 0.05;
    const afterDiscount = subtotal - tierDiscount;
    const vat = roundCents(afterDiscount * 0.21);
    assert.equal(totals.subtotal, subtotal);
    assert.equal(totals.discount, tierDiscount);
    assert.equal(totals.vat, vat);
  });
});

describe('addLine', () => {
  it('adds a new line to an invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3 });

    assert(addResult.ok);
    assert.equal(addResult.value.lines.length, 2);
    assert.equal(addResult.value.lines[1].sku, 'DEV-HOUR');
    assert.equal(addResult.value.lines[1].qty, 3);
    assert.equal(addResult.value.lines[1].name, 'Development (hour)');
  });

  it('increases qty if SKU already exists', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DES-HOUR', qty: 3 });

    assert(addResult.ok);
    assert.equal(addResult.value.lines.length, 1);
    assert.equal(addResult.value.lines[0].sku, 'DES-HOUR');
    assert.equal(addResult.value.lines[0].qty, 8);
  });

  it('returns QTY_INVALID for zero quantity', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 0 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for negative quantity', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: -2 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'QTY_INVALID');
  });

  it('returns QTY_INVALID for fractional quantity', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 2.5 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'QTY_INVALID');
  });

  it('returns UNKNOWN_SKU for invalid SKU', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'INVALID', qty: 1 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'UNKNOWN_SKU');
  });

  it('returns NOT_DRAFT for non-draft invoice', () => {
    const invoice = {
      customerId: 'C-001',
      issueDate: '2025-12-15',
      status: 'sent',
      lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
    };

    const addResult = addLine(invoice, { sku: 'DEV-HOUR', qty: 3 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'NOT_DRAFT');
  });

  it('does not mutate the original invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const originalLines = invoiceResult.value.lines.length;
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3 });

    assert(addResult.ok);
    assert.equal(invoiceResult.value.lines.length, originalLines);
  });

  it('adds a line with discount', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 15 });

    assert(addResult.ok);
    assert.equal(addResult.value.lines.length, 2);
    assert.equal(addResult.value.lines[1].sku, 'DEV-HOUR');
    assert.equal(addResult.value.lines[1].discountPercent, 15);
  });

  it('returns DISCOUNT_INVALID for invalid discount on addLine', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3, discountPercent: 150 });

    assert(!addResult.ok);
    assert.equal(addResult.error, 'DISCOUNT_INVALID');
  });

  it('defaults discount to 0 when adding new line without discount', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-002',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const addResult = addLine(invoiceResult.value, { sku: 'DEV-HOUR', qty: 3 });

    assert(addResult.ok);
    assert.equal(addResult.value.lines[1].discountPercent, 0);
  });
});

describe('removeLine', () => {
  it('removes a line from an invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const removeResult = removeLine(invoiceResult.value, 'DES-HOUR');

    assert(removeResult.ok);
    assert.equal(removeResult.value.lines.length, 1);
    assert.equal(removeResult.value.lines[0].sku, 'DEV-HOUR');
  });

  it('returns LINE_NOT_FOUND for non-existent SKU', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const removeResult = removeLine(invoiceResult.value, 'INVALID');

    assert(!removeResult.ok);
    assert.equal(removeResult.error, 'LINE_NOT_FOUND');
  });

  it('returns NO_LINES if removing the last line', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const removeResult = removeLine(invoiceResult.value, 'DES-HOUR');

    assert(!removeResult.ok);
    assert.equal(removeResult.error, 'NO_LINES');
  });

  it('returns NOT_DRAFT for non-draft invoice', () => {
    const invoice = {
      customerId: 'C-001',
      issueDate: '2025-12-15',
      status: 'sent',
      lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
    };

    const removeResult = removeLine(invoice, 'DES-HOUR');

    assert(!removeResult.ok);
    assert.equal(removeResult.error, 'NOT_DRAFT');
  });

  it('does not mutate the original invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const originalLines = invoiceResult.value.lines.length;
    const removeResult = removeLine(invoiceResult.value, 'DES-HOUR');

    assert(removeResult.ok);
    assert.equal(invoiceResult.value.lines.length, originalLines);
  });
});

describe('issueInvoice', () => {
  it('issues a draft invoice with a number and status "issued"', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const issueResult = issueInvoice(invoiceResult.value, []);

    assert(issueResult.ok);
    assert.equal(issueResult.value.number, 'INV-2025-0001');
    assert.equal(issueResult.value.status, 'issued');
    assert.equal(issueResult.value.customerId, 'C-001');
    assert.equal(issueResult.value.issueDate, '2025-12-15');
    assert.equal(issueResult.value.lines.length, 1);
  });

  it('assigns the next number when numbers already exist', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const existingNumbers = ['INV-2025-0001', 'INV-2025-0002'];
    const issueResult = issueInvoice(invoiceResult.value, existingNumbers);

    assert(issueResult.ok);
    assert.equal(issueResult.value.number, 'INV-2025-0003');
  });

  it('assigns number from different year when issuing in new year', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2026-01-10',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const existingNumbers = ['INV-2025-0001', 'INV-2025-0002'];
    const issueResult = issueInvoice(invoiceResult.value, existingNumbers);

    assert(issueResult.ok);
    assert.equal(issueResult.value.number, 'INV-2026-0001');
  });

  it('returns NOT_DRAFT for non-draft invoice', () => {
    const invoice = {
      number: 'INV-2025-0001',
      customerId: 'C-001',
      issueDate: '2025-12-15',
      status: 'issued',
      lines: [{ sku: 'DES-HOUR', qty: 5, name: 'Design work (hour)', unitPrice: 8500, vatRate: 21 }],
    };

    const issueResult = issueInvoice(invoice, []);

    assert(!issueResult.ok);
    assert.equal(issueResult.error, 'NOT_DRAFT');
  });

  it('preserves line items', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [
        { sku: 'DES-HOUR', qty: 5 },
        { sku: 'DEV-HOUR', qty: 3 },
      ],
    });

    assert(invoiceResult.ok);
    const issueResult = issueInvoice(invoiceResult.value, []);

    assert(issueResult.ok);
    assert.equal(issueResult.value.lines.length, 2);
    assert.equal(issueResult.value.lines[0].sku, 'DES-HOUR');
    assert.equal(issueResult.value.lines[0].qty, 5);
    assert.equal(issueResult.value.lines[1].sku, 'DEV-HOUR');
    assert.equal(issueResult.value.lines[1].qty, 3);
  });

  it('does not mutate the original invoice', () => {
    const invoiceResult = createInvoice({
      customerId: 'C-001',
      issueDate: '2025-12-15',
      lines: [{ sku: 'DES-HOUR', qty: 5 }],
    });

    assert(invoiceResult.ok);
    const originalStatus = invoiceResult.value.status;
    const originalLines = invoiceResult.value.lines.length;
    const issueResult = issueInvoice(invoiceResult.value, []);

    assert(issueResult.ok);
    assert.equal(invoiceResult.value.status, originalStatus);
    assert.equal(invoiceResult.value.lines.length, originalLines);
    assert(!invoiceResult.value.number);
  });
});

